#!/usr/bin/env python3
"""F-SPLIT-03 (flows over the socket, D-S5-01): `RemoteFlowsJobs`, the six generated remote objects of the FLOWS jobs composed as one `FlowsJobs`.

Reads `crates/iyakki-agent-api/src/flows_jobs.rs` (the six job traits) and writes `crates/iyakki-ui-rpc/src/gen_flows_jobs.rs`: a struct that holds the six
`Remote<Job>` objects and implements every job trait by calling the matching object. `--check` writes nothing and fails when the file is stale.
Usage: dist/split/gen_flows_jobs.py [--check]"""
import re, os, sys
ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
SRC = ROOT + '/crates/iyakki-agent-api/src/flows_jobs.rs'
OUT = ROOT + '/crates/iyakki-ui-rpc/src/gen_flows_jobs.rs'
JOBS = ['Meta', 'Drafts', 'Runs', 'Assist', 'Hooks', 'Channel']

def split_args(a):
    out, d, cur = [], 0, ''
    a = a.replace('->', '\x00')
    for c in a:
        if c in '<([': d += 1
        if c in '>)]': d -= 1
        if c == ',' and d == 0: out.append(cur.strip().replace('\x00', '->')); cur = ''; continue
        cur += c
    if cur.strip(): out.append(cur.strip().replace('\x00', '->'))
    return out

def build():
    src = open(SRC).read()
    uses = re.findall(r'^use [^\n]*;$', src, flags=re.M)
    out = ['// @generated by dist/split/gen_flows_jobs.py from crates/iyakki-agent-api/src/flows_jobs.rs: do not edit by hand.',
           '//! `RemoteFlowsJobs`: the six remote objects of the FLOWS jobs as one `FlowsJobs` (F-SPLIT-03, D-S5-01).',
           '#![allow(clippy::too_many_arguments, unused_variables)]', '']
    out += uses
    out += ['use iyakki_agent_api::{FlowsAssist, FlowsChannel, FlowsDrafts, FlowsHooks, FlowsJobs, FlowsMeta, FlowsRuns};']
    out += ['', 'use crate::gen_remote::{RemoteFlowsAssist, RemoteFlowsChannel, RemoteFlowsDrafts, RemoteFlowsHooks, RemoteFlowsMeta, RemoteFlowsRuns};', '',
            '/// The jobs of one account\'s flows environment, each a remote object of the core.', 'pub struct RemoteFlowsJobs {']
    for j in JOBS: out.append('    pub(crate) %s: RemoteFlows%s,' % (j.lower(), j))
    out += ['}', '']
    for j in JOBS:
        m = re.search(r'pub trait Flows%s: Send \+ Sync \{(.*?)\n\}' % j, src, flags=re.S)
        assert m, j
        out.append('impl Flows%s for RemoteFlowsJobs {' % j)
        for sig in re.finditer(r'^    fn (\w+)\(&self(?:,\s*(.*?))?\)(\s*->\s*[^;]+)?;\s*$', m.group(1), flags=re.M):
            name, args, ret = sig.group(1), (sig.group(2) or '').replace('crate::', 'iyakki_agent_api::'), (sig.group(3) or '').strip().replace('crate::', 'iyakki_agent_api::')
            names = [a.split(':')[0].strip() for a in split_args(args)]
            out.append('    fn %s(&self%s)%s {' % (name, (', ' + args) if args else '', (' ' + ret) if ret else ''))
            out.append('        self.%s.%s(%s)' % (j.lower(), name, ', '.join(names)))
            out.append('    }')
        out.append('}')
        out.append('')
    out.append('impl FlowsJobs for RemoteFlowsJobs {}')
    out.append('')
    # the core's end: the same six traits over the real environment, the person read again (a `by` the UI claims is never used, D-S5-02)
    out += ['/// The core\'s end of the six objects: the real environment with the person read again. A `by` or an `approved_by` the UI claims is replaced by the',
            '/// account\'s own name (`who()`), a card decision carries that name too: the UI cannot act as somebody else.',
            'pub struct GuardedFlowsJobs(pub Arc<dyn FlowsJobs>);', '']
    for j in JOBS:
        m = re.search(r'pub trait Flows%s: Send \+ Sync \{(.*?)\n\}' % j, src, flags=re.S)
        out.append('impl Flows%s for GuardedFlowsJobs {' % j)
        for sig in re.finditer(r'^    fn (\w+)\(&self(?:,\s*(.*?))?\)(\s*->\s*[^;]+)?;\s*$', m.group(1), flags=re.M):
            name, args, ret = sig.group(1), (sig.group(2) or '').replace('crate::', 'iyakki_agent_api::'), (sig.group(3) or '').strip().replace('crate::', 'iyakki_agent_api::')
            call = []
            for a in split_args(args):
                n = a.split(':')[0].strip()
                if n == 'by': call.append('&self.0.who()')
                elif n == 'approved_by': call.append('approved_by.map(|_| self.0.who())')
                elif n == 'd' and 'CardDecision' in a: call.append('by_who(d, &self.0.who())')
                elif n == 'req' and 'StartRequest' in a: call.append('started_by(req, &self.0.who())')
                else: call.append(n)
            out.append('    fn %s(&self%s)%s {' % (name, (', ' + args) if args else '', (' ' + ret) if ret else ''))
            out.append('        self.0.%s(%s)' % (name, ', '.join(call)))
            out.append('    }')
        out.append('}')
        out.append('')
    out.append('impl FlowsJobs for GuardedFlowsJobs {}')
    out += ['', '/// A run request whose trigger names the account\'s own name as the person (a `by` the UI claims is dropped).', 'fn started_by(mut req: StartRequest, who: &str) -> StartRequest {', '    req.trigger.by = who.into();', '    req', '}']
    out += ['', '/// The card decision with the person replaced by the account\'s own name.', 'fn by_who(d: CardDecision, who: &str) -> CardDecision {', '    match d {',
            '        CardDecision::Approve { .. } => CardDecision::Approve { by: who.into() },', '        CardDecision::Reject { note, .. } => CardDecision::Reject { by: who.into(), note },',
            '        CardDecision::Edit { patch, .. } => CardDecision::Edit { by: who.into(), patch },', '        CardDecision::Investigate { .. } => CardDecision::Investigate { by: who.into() },', '    }', '}']
    return '\n'.join(out) + '\n'

if __name__ == '__main__':
    text = build()
    if '--check' in sys.argv:
        if not os.path.exists(OUT) or open(OUT).read() != text:
            print('gen_flows_jobs.rs is stale: run dist/split/gen_flows_jobs.py'); sys.exit(1)
        print('gen_flows_jobs.rs is current'); sys.exit(0)
    open(OUT, 'w').write(text); print('wrote', OUT)
